82	    /**
83	     * Dedicated audit logger. On a successful create an audit line carrying the new owner's id,
84	     * {@code memberId}, {@code registrationDate} and {@code membershipLevel} is emitted to the
85	     * logger named {@code AUDIT}.
86	     */
