96	    /**
97	     * Monotonically increasing sequence number stamped onto each structured {@link OwnerCreatedEvent}.
98	     * Shared across all creates so the events carry a total order independent of the owner id.
99	     */
100	    private static final AtomicLong AUDIT_SEQUENCE = new AtomicLong();
