102	    /**
103	     * Syntactic check for an email address: a non-empty local part, an {@code @}, and a domain with
104	     * at least one dot and no whitespace on either side.
105	     */
106	    private static final Pattern EMAIL_PATTERN =
107	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
108	
109	    /**
110	     * Disposable email domains that an owner's email may not use. An email whose domain (the part
111	     * after the {@code @}, compared case-insensitively) is on this list is rejected with a 400
112	     * response naming {@code email}.
113	     */
114	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
115	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
