117	    /**
118	     * Common street-type abbreviations expanded during address normalization. Keys are the
119	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
120	     * expanded form.
121	     */
122	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
123	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
124	
125	    /**
126	     * Required national-number length per E.164 country code (the digits that follow the country
127	     * code). {@code '+61'} (Australia) requires 9 national digits; {@code '+1'} (NANP) requires 10.
128	     * A country code that is not listed here is not length-checked, keeping other numbers accepted.
129	     */
130	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH =
131	        Map.of("1", 10, "61", 9);
132	
133	    /**
134	     * Inclusive 4-digit postcode range allowed for each known region, keyed by the region an owner's
135	     * city derives to (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD): NSW 2000-2099, VIC
136	     * 3000-3099, QLD 4000-4099. A city that derives to no known region ({@code "UNKNOWN"}) is not in
137	     * this table and accepts any 4-digit postcode.
138	     */
139	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
140	        "NSW", new int[] {2000, 2099},
141	        "VIC", new int[] {3000, 3099},
142	        "QLD", new int[] {4000, 4099});
