144	    /**
145	     * The maximum number of owners a single city may contain. A create request for a city that
146	     * already holds this many owners is rejected with a 409 response.
147	     */
148	    private static final int MAX_OWNERS_PER_CITY = 50;
149	
150	    /**
151	     * The number of owners a city must already contain for a create in that city to be flagged as
152	     * approaching capacity. When an existing city holds at least this many owners but fewer than
153	     * {@value #MAX_OWNERS_PER_CITY} (so the create is still accepted), the new owner is created with
154	     * {@code capacityWarning} set to {@code true}.
155	     */
156	    private static final int CAPACITY_WARNING_THRESHOLD = 40;
157	
158	    /**
159	     * The maximum number of owners that may be registered in a single day. A create request made
160	     * once this many owners already carry today's {@code registrationDate} is rejected with a 429
161	     * response.
162	     */
163	    private static final int MAX_OWNERS_PER_DAY = 100;
164	
165	    /**
166	     * The number of owners that must already carry a day's {@code registrationDate} before a create
167	     * for that day is flagged as a bulk signup. Once more than this many owners already exist for the
168	     * day, the new owner is created with {@code bulkSignupWarning} set to {@code true}.
169	     */
170	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
171	
172	    /**
173	     * The tenure, in elapsed fiscal years, an owner must exceed to reach {@code membershipLevel} 4.
174	     * Tenure accrues from membership, so a newly created owner (zero tenure) never clears this
175	     * threshold and is therefore capped at level 3 on create.
176	     */
177	    private static final int TENURE_LEVEL_THRESHOLD_FISCAL_YEARS = 1;
