235	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
236	    @Override
237	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
238	        String idempotencyKey = idempotencyKey();
239	        if (idempotencyKey != null) {
240	            Integer existingId = this.idempotentCreates.get(idempotencyKey);
241	            if (existingId != null) {
242	                Owner existing = this.clinicService.findOwnerById(existingId);
243	                if (existing != null) {
244	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
245	                }
246	            }
247	        }
248	        normalizeAddress(ownerFieldsDto);
249	        validateRequiredFields(ownerFieldsDto);
250	        normalizeTelephone(ownerFieldsDto);
251	        normalizeEmail(ownerFieldsDto);
252	        validatePostcode(ownerFieldsDto);
253	        String householdId = computeHouseholdId(ownerFieldsDto);
254	        rejectDuplicate(ownerFieldsDto);
255	        rejectCityAtCapacity(ownerFieldsDto);
256	        resolveRegistrationDate(ownerFieldsDto);
257	        rejectDailyLimitReached(ownerFieldsDto.getRegistrationDate());
258	        HttpHeaders headers = new HttpHeaders();
259	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
260	        owner.setHouseholdId(householdId);
261	        assignMemberId(owner);
262	        assignNamesakeCount(owner);
263	        assignBulkSignupWarning(owner);
264	        assignCapacityWarning(owner);
265	        assignPossibleDuplicate(owner, ownerFieldsDto);
266	        assignHouseholdMembership(owner);
267	        assignMembership(owner);
268	        this.clinicService.saveOwner(owner);
269	        if (idempotencyKey != null) {
270	            this.idempotentCreates.put(idempotencyKey, owner.getId());
271	        }
272	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
273	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
274	        emitOwnerCreatedEvent(owner);
275	        enqueueWelcomeNotification(owner);
276	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
277	        headers.setLocation(UriComponentsBuilder.newInstance()
278	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
279	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
280	    }
