282	    /**
283	     * Emits the immutable structured {@link OwnerCreatedEvent} for a just-persisted owner to the
284	     * {@code AUDIT} logger as a JSON object, alongside the human-readable audit line. Each event is
285	     * stamped with the next value of {@link #AUDIT_SEQUENCE} (monotonically increasing across creates)
286	     * and carries the owner's current primary identifier via {@link #primaryIdentifier}.
287	     */
288	    private void emitOwnerCreatedEvent(Owner owner) {
289	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_SEQUENCE.incrementAndGet(), owner.getId(),
290	            primaryIdentifier(owner), owner.getMembershipLevel());
291	        AUDIT.info(event.toJson());
292	    }
