410	    /**
411	     * Returns the trimmed {@code Idempotency-Key} header of the current request, or {@code null} when
412	     * the header is absent, blank or there is no active request. A present key opts a create into the
413	     * idempotent-repeat behaviour tracked by {@link #idempotentCreates}.
414	     */
415	    private String idempotencyKey() {
416	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
417	            return null;
418	        }
419	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
420	        if (key == null || key.trim().isEmpty()) {
421	            return null;
422	        }
423	        return key.trim();
424	    }
