427	        List<String> missingFields = new ArrayList<>();
428	        if (isBlank(ownerFieldsDto.getFirstName())) {
429	            missingFields.add("firstName");
430	        }
431	        if (isBlank(ownerFieldsDto.getLastName())) {
432	            missingFields.add("lastName");
433	        }
434	        if (isBlank(ownerFieldsDto.getAddress())) {
435	            missingFields.add("address");
436	        }
437	        if (isBlank(ownerFieldsDto.getCity())) {
438	            missingFields.add("city");
439	        }
440	        if (isBlank(ownerFieldsDto.getTelephone())) {
441	            missingFields.add("telephone");
442	        }
443	        if (!missingFields.isEmpty()) {
444	            throw new InvalidOwnerFieldsException(missingFields);
445	        }
