452	    /**
453	     * Normalizes an owner's address on create, supporting both the structured form
454	     * ({@code addressLine1} plus optional {@code addressLine2}) and the flat {@code address} form kept
455	     * for backward compatibility. Whichever fields are supplied are canonicalized in place - trimmed,
456	     * internal whitespace runs collapsed to a single space, upper-cased and common street-type
457	     * abbreviations expanded as whole tokens ({@code ST}->{@code STREET}, {@code RD}->{@code ROAD},
458	     * {@code AVE}->{@code AVENUE}). The canonical {@code addressLine1}/{@code addressLine2} are written
459	     * back, and the composed {@code address} - the normalized {@code addressLine1} with a single space
460	     * and the normalized {@code addressLine2} appended when present, falling back to the normalized
461	     * flat {@code address} when no structured line is given - is written onto the request so it is what
462	     * gets validated, compared, stored and returned. Running before the required-field check means an
463	     * address that is blank in both forms after normalization is rejected like a missing one.
464	     */
465	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
466	        String line1 = canonicalAddress(ownerFieldsDto.getAddressLine1());
467	        String line2 = canonicalAddress(ownerFieldsDto.getAddressLine2());
468	        String flat = canonicalAddress(ownerFieldsDto.getAddress());
469	        ownerFieldsDto.setAddressLine1(line1);
470	        ownerFieldsDto.setAddressLine2(line2);
471	        ownerFieldsDto.setAddress(composeAddress(line1, line2, flat));
472	    }
473	
474	    /**
475	     * Composes the effective address, preferring the structured form: when {@code line1} is present
476	     * (non-blank) the result is {@code line1}, with a single space and {@code line2} appended when
477	     * {@code line2} is present; otherwise the flat {@code address} is used. All three inputs are
478	     * expected to be already canonicalized. Returns the flat value (which may be {@code null} or blank,
479	     * left for the required-field check to reject) when no structured line is supplied.
480	     */
481	    private static String composeAddress(String line1, String line2, String flat) {
482	        if (line1 != null && !line1.isBlank()) {
483	            if (line2 != null && !line2.isBlank()) {
484	                return line1 + " " + line2;
485	            }
486	            return line1;
487	        }
488	        return flat;
489	    }
490	
491	    /**
492	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
493	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
494	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
495	     * address is returned unchanged, making it safe to apply to stored values during comparison.
496	     */
497	    private static String canonicalAddress(String address) {
498	        if (address == null) {
499	            return null;
500	        }
501	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
502	        if (collapsed.isEmpty()) {
503	            return "";
504	        }
505	        String[] tokens = collapsed.split(" ");
506	        StringBuilder sb = new StringBuilder(collapsed.length());
507	        for (int i = 0; i < tokens.length; i++) {
508	            if (i > 0) {
509	                sb.append(' ');
510	            }
511	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
512	        }
513	        return sb.toString();
514	    }
515	
516	    /**
517	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
518	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
519	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
520	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}, and when the
521	     * country code is one whose national-number length is known ({@code '+61'} => 9 national digits,
522	     * {@code '+1'} => 10) the national number must have exactly that many digits. The E.164 string is
523	     * written back onto the request so it is what gets stored and returned. Any value that cannot
524	     * form a valid E.164 number is rejected with a 400 response whose {@code errors} array names
525	     * {@code telephone}.
526	     */
527	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
528	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
529	    }
