531	    /**
532	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
533	     * (400) naming {@code telephone} when it cannot form a valid number.
534	     */
535	    private static String toE164(String telephone) {
536	        if (telephone == null) {
537	            throw new InvalidOwnerFieldsException(List.of("telephone"));
538	        }
539	        boolean hasCountryCode = telephone.trim().startsWith("+");
540	        String digits = telephone.replaceAll("\\D", "");
541	        String countryCode;
542	        String national;
543	        if (hasCountryCode) {
544	            countryCode = matchCountryCode(digits);
545	            national = digits;
546	        } else {
547	            countryCode = "61";
548	            if (digits.startsWith("0")) {
549	                digits = digits.substring(1);
550	            }
551	            national = "61" + digits;
552	        }
553	        if (!national.matches("[0-9]{8,15}")) {
554	            throw new InvalidOwnerFieldsException(List.of("telephone"));
555	        }
556	        if (countryCode != null) {
557	            Integer requiredLength = COUNTRY_NATIONAL_LENGTH.get(countryCode);
558	            if (requiredLength != null
559	                && national.length() - countryCode.length() != requiredLength) {
560	                throw new InvalidOwnerFieldsException(List.of("telephone"));
561	            }
562	        }
563	        return "+" + national;
564	    }
