566	    /**
567	     * Returns the longest known E.164 country code (a key of {@link #COUNTRY_NATIONAL_LENGTH}) that
568	     * the given country-code-prefixed digit string starts with, or {@code null} when none is known so
569	     * the number is not length-checked against a country.
570	     */
571	    private static String matchCountryCode(String digits) {
572	        return COUNTRY_NATIONAL_LENGTH.keySet().stream()
573	            .filter(digits::startsWith)
574	            .max(Comparator.comparingInt(String::length))
575	            .orElse(null);
576	    }
