578	    /**
579	     * Rejects creating an owner that duplicates an existing one on the derived {@code identityKey} -
580	     * the SHA-256 hex digest of {@code normalizedTelephone + '|' + lowerEmail + '|' +
581	     * soundex(lastName)} (see {@link IdentityKey}). An exact key match means the same telephone, email
582	     * and same-sounding surname, i.e. the same person re-registering; because the telephone is part of
583	     * the key, two people who merely share a surname (and postcode) but carry different telephones no
584	     * longer collide here - they are surfaced as a soft match instead (see
585	     * {@link #assignPossibleDuplicate}). This single identity key is the only hard-duplicate rule; the
586	     * computed {@code householdId} no longer contributes a separate 409. A match is a 409.
587	     *
588	     * <p>Owners flagged {@code deleted} (soft-deleted via {@code DELETE /api/owners/{id}}) are skipped
589	     * entirely, so a normally-blocking duplicate is allowed when the only matching owner has been
590	     * deleted.
591	     *
592	     * <p>The {@code sharesHousehold} flag bypasses the entire duplicate block. The incoming telephone
593	     * and email have already been normalized by {@link #normalizeTelephone} and {@link #normalizeEmail}
594	     * (the email-domain blocklist applies first, in {@link #normalizeEmail}); each existing owner's key
595	     * is derived the same way before comparison. A match results in a 409 response naming
596	     * {@code identityKey}.
597	     */
598	    private void rejectDuplicate(OwnerFieldsDto ownerFieldsDto) {
599	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
600	            return;
601	        }
602	        String identityKey = IdentityKey.of(ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(),
603	            ownerFieldsDto.getLastName());
604	        for (Owner existing : this.clinicService.findAllOwners()) {
605	            if (Boolean.TRUE.equals(existing.getDeleted())) {
606	                continue;
607	            }
608	            if (identityKey.equals(existingIdentityKey(existing))) {
609	                throw new DuplicateOwnerIdentityException(identityKey);
610	            }
611	        }
612	    }
