692	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
693	     * written back onto the request so that is what gets stored and returned. A present but invalid
694	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
695	     */
696	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
697	        String email = ownerFieldsDto.getEmail();
698	        if (email == null) {
699	            return;
