713	    /**
714	     * Validates an owner's optional {@code postcode} on create. The field may be omitted entirely
715	     * (so an owner created without a postcode stays accepted), but when a value is present it must be
716	     * exactly 4 digits and valid for the region the owner's {@code city} derives to: NSW 2000-2099,
717	     * VIC 3000-3099, QLD 4000-4099. A city with no known region accepts any 4-digit postcode. A
718	     * present postcode that is malformed or out of range for the city's region is rejected with a 400
719	     * response whose {@code errors} array names {@code postcode}. A valid value is left on the request
720	     * as-is so it is stored and returned.
721	     */
722	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
723	        String postcode = ownerFieldsDto.getPostcode();
724	        if (postcode == null) {
