727	        if (!postcode.matches("[0-9]{4}")) {
728	            throw new InvalidOwnerFieldsException(List.of("postcode"));
729	        }
730	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.derive(ownerFieldsDto.getCity()));
731	        if (range != null) {
732	            int value = Integer.parseInt(postcode);
