739	    /**
740	     * Resolves an owner's effective {@code registrationDate} on create and rolls it onto a business
741	     * day. When the caller supplies no value it defaults to the server's current date; a value
742	     * provided in the request is kept. A supplied value later than the server's current date is
743	     * rejected with a 400 response whose {@code errors} array names {@code registrationDate}. The
744	     * effective date, whether supplied or defaulted, must fall on a business day: a Saturday or
745	     * Sunday is rolled forward to the following Monday. The adjusted date is written back onto the
746	     * request so it is what gets stored and returned (in ISO {@code YYYY-MM-DD} format) and what
747	     * every value derived from the registration date is based on.
748	     */
749	    private void resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
750	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
751	        if (effective == null) {
752	            effective = LocalDate.now();
753	        }
754	        else if (effective.isAfter(LocalDate.now())) {
755	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
756	        }
757	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
758	    }
