760	    /**
761	     * The fixed public-holiday calendar. A registration date landing on one of these days is rolled
762	     * forward, just like a weekend, until it reaches a non-holiday business day.
763	     */
764	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
765	        LocalDate.of(2026, 1, 1),
766	        LocalDate.of(2026, 1, 26),
767	        LocalDate.of(2026, 4, 25),
768	        LocalDate.of(2026, 12, 25),
769	        LocalDate.of(2026, 12, 28));
770	
771	    /**
772	     * Rolls a date forward onto a business day: a Saturday, Sunday or listed public holiday is
773	     * advanced one day at a time until it reaches the next non-holiday business day; a weekday that
774	     * is not a holiday is returned unchanged.
775	     */
776	    private static LocalDate toBusinessDay(LocalDate date) {
777	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
778	            date = date.plusDays(1);
779	        }
780	        return date;
781	    }
