783	    /**
784	     * Returns whether the given date falls on a Saturday or Sunday.
785	     */
786	    private static boolean isWeekend(LocalDate date) {
787	        return switch (date.getDayOfWeek()) {
788	            case SATURDAY, SUNDAY -> true;
789	            default -> false;
790	        };
791	    }
