793	    /**
794	     * Assigns the owner's unified {@code memberId} on create, formatted
795	     * {@code '<REGIONV2><FY><HASH8><CHK>'} where {@code REGIONV2} is the version-2 region code (the
796	     * region the owner's identity derives to from its postcode, falling back to the city table when
797	     * the postcode is absent or in no known range, with the fixed {@code 'V2'} version tag mixed in
798	     * via {@link OwnerLocality#regionCodeV2} so the member id never reproduces a version-1 value),
799	     * {@code FY} is the two-digit fiscal year of the business-day-adjusted
800	     * {@code registrationDate} (the fiscal year starts on 1 July, e.g. a registration on 2026-08-03
801	     * falls in fiscal year 2027 and yields {@code '27'}), {@code HASH8} is the first eight upper-case
802	     * hex characters of the SHA-256 digest of the normalized telephone concatenated with the last
803	     * name, and {@code CHK} is a single Luhn check digit over the digits of the
804	     * {@code '<REGIONV2><FY><HASH8>'} body (e.g. {@code 'NSWV271A2B3C4D4'}). The telephone has already
805	     * been normalized to E.164 form by {@link #normalizeTelephone} and {@code registrationDate} has
806	     * been defaulted, so both inputs are present. The identity is a pure function of region, fiscal
807	     * year, telephone and last name; the check digit is computed over the body before any
808	     * collision-handling suffix is applied.
809	     */
810	    private void assignMemberId(Owner owner) {
811	        String region = OwnerLocality.regionCodeV2(OwnerLocality.derive(owner.getCity(), owner.getPostcode()));
812	        String fy = String.format("%02d", FiscalYear.yearOf(owner.getRegistrationDate()) % 100);
813	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName(), 8);
814	        String body = region + fy + hash8;
815	        int chk = MemberIdCheckDigit.of(body);
816	        owner.setMemberId(deduplicateMemberId(body + chk));
817	    }
