819	    /**
820	     * Returns {@code memberId} unchanged when no existing owner already carries it; otherwise appends
821	     * {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a value not held by any
822	     * existing owner. Compared against the pre-existing owners, so the returned member id is unique
823	     * among them.
824	     */
825	    private String deduplicateMemberId(String memberId) {
826	        Set<String> existing = new HashSet<>();
827	        for (Owner owner : this.clinicService.findAllOwners()) {
828	            if (owner.getMemberId() != null) {
829	                existing.add(owner.getMemberId());
830	            }
831	        }
832	        if (!existing.contains(memberId)) {
833	            return memberId;
834	        }
835	        int n = 2;
836	        while (existing.contains(memberId + "-" + n)) {
837	            n++;
838	        }
839	        return memberId + "-" + n;
840	    }
