860	    /**
861	     * Assigns the new owner's {@code membershipPoints} and derived {@code membershipLevel} on create.
862	     * Points start at 0 and accrue: plus 2 when an email is present, plus 1 when {@code namesakeCount}
863	     * is 0, plus 2 for a household of 3 or more members, and plus 3 for tenure exceeding
864	     * {@value #TENURE_LEVEL_THRESHOLD_FISCAL_YEARS} elapsed fiscal year. The points are then mapped to a level of 1 (0-1
865	     * points), 2 (2-3), 3 (4-5), or 4 (6 or more). Runs after {@link #assignNamesakeCount} and
866	     * {@link #assignHouseholdMembership} so those counts are settled. A newly created owner has zero
867	     * tenure, so the tenure bonus never applies on create.
868	     */
869	    private void assignMembership(Owner owner) {
870	        int points = 0;
871	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
872	            points += 2;
873	        }
874	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
875	            points += 1;
876	        }
877	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
878	            points += 2;
879	        }
880	        if (tenureFiscalYears(owner) > TENURE_LEVEL_THRESHOLD_FISCAL_YEARS) {
881	            points += 3;
882	        }
883	        owner.setMembershipPoints(points);
884	        owner.setMembershipLevel(capMembershipLevelByHousehold(owner, membershipLevelForPoints(points)));
885	    }
