887	    /**
888	     * Caps a newly derived {@code membershipLevel} so it cannot exceed one above the current maximum
889	     * {@code membershipLevel} among the new owner's existing household members - the pre-existing owners
890	     * already carrying the same {@code householdId}. When the owner belongs to no household, or has no
891	     * existing household member, no cap applies and the derived level is returned unchanged. Runs after
892	     * {@link #assignHouseholdMembership} so the owner's {@code householdId} is settled.
893	     */
894	    private int capMembershipLevelByHousehold(Owner owner, int derivedLevel) {
895	        String householdId = owner.getHouseholdId();
896	        if (householdId == null || householdId.isBlank()) {
897	            return derivedLevel;
898	        }
899	        Integer maxHouseholdLevel = null;
900	        for (Owner existing : this.clinicService.findAllOwners()) {
901	            if (householdId.equals(existing.getHouseholdId()) && existing.getMembershipLevel() != null
902	                && (maxHouseholdLevel == null || existing.getMembershipLevel() > maxHouseholdLevel)) {
903	                maxHouseholdLevel = existing.getMembershipLevel();
904	            }
905	        }
906	        if (maxHouseholdLevel == null) {
907	            return derivedLevel;
908	        }
909	        return Math.min(derivedLevel, maxHouseholdLevel + 1);
910	    }
