912	    /**
913	     * Maps {@code membershipPoints} to a {@code membershipLevel}: 1 for 0-1 points, 2 for 2-3, 3 for
914	     * 4-5, and 4 for 6 or more points.
915	     */
916	    private int membershipLevelForPoints(int points) {
917	        if (points <= 1) {
918	            return 1;
919	        }
920	        if (points <= 3) {
921	            return 2;
922	        }
923	        if (points <= 5) {
924	            return 3;
925	        }
926	        return 4;
927	    }
