990	     * has deliberately opted into an existing household, so its shared last name and postcode are
991	     * expected rather than a suspected duplicate.
992	     */
993	    private void assignPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
994	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
995	            owner.setPossibleDuplicate(false);
996	            owner.setPossibleDuplicateOf(null);
997	            return;
998	        }
999	        String postcode = owner.getPostcode();
1000	        String soundex = IdentityKey.soundex(owner.getLastName());
1001	        String identityKey = IdentityKey.of(owner.getTelephone(), owner.getEmail(), owner.getLastName());
1002	        Integer matchId = null;
1003	        if (postcode != null && !postcode.isBlank()) {
1004	            for (Owner existing : this.clinicService.findAllOwners()) {
1005	                if (soundex.equals(IdentityKey.soundex(existing.getLastName()))
1006	                    && postcode.equals(existing.getPostcode())
1007	                    && !identityKey.equals(existingIdentityKey(existing))
1008	                    && existing.getId() != null
1009	                    && (matchId == null || existing.getId() < matchId)) {
1010	                    matchId = existing.getId();
1011	                }
1012	            }
