1018	    /**
1019	     * Computes the new owner's deterministic {@code householdId}: the first twelve upper-case hex
1020	     * characters of the SHA-256 digest of {@code "V2|<normalizedLastName>|<postcode>"}, where the
1021	     * leading {@code V2} is the fixed version-2 tag ({@link OwnerLocality#IDENTITY_VERSION_TAG}) mixed
1022	     * in so no version-1 household id is reproduced, and the last
1023	     * name is normalized for comparison (trimmed, internal whitespace collapsed, lower-cased) and the
1024	     * postcode is the already-validated 4-digit value. Because it is a pure function of the last name
1025	     * and postcode, any two owners sharing those - regardless of creation order or whether they opted
1026	     * into {@code sharesHousehold} - land in the same household automatically. Returns {@code null}
1027	     * when the owner has no postcode, so such owners belong to no household. This single value feeds
1028	     * both the duplicate detection ({@link #rejectDuplicate}) and the household-size count
1029	     * ({@link #assignHouseholdMembership}).
1030	     */
1031	    private String computeHouseholdId(OwnerFieldsDto ownerFieldsDto) {
1032	        String postcode = ownerFieldsDto.getPostcode();
1033	        if (postcode == null || postcode.isBlank()) {
1034	            return null;
1035	        }
1036	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
1037	        return shaHexUpper(OwnerLocality.IDENTITY_VERSION_TAG + "|" + lastName + "|" + postcode, 12);
1038	    }
1039	
1040	    /**
1041	     * Assigns the new owner's {@code householdMemberCount} on create: the number of owners sharing
1042	     * the new owner's {@code householdId} once this create is applied — that is, the new owner plus
1043	     * every existing owner already carrying the same identifier. Runs after the owner's
1044	     * {@code householdId} has been set from {@link #computeHouseholdId} so the identifier is settled.
1045	     * Left {@code null} when the owner belongs to no household.
1046	     */
1047	    private void assignHouseholdMembership(Owner owner) {
1048	        String householdId = owner.getHouseholdId();
1049	        if (householdId == null || householdId.isBlank()) {
1050	            owner.setHouseholdMemberCount(null);
1051	            return;
1052	        }
1053	        int count = 1;
1054	        for (Owner existing : this.clinicService.findAllOwners()) {
1055	            if (householdId.equals(existing.getHouseholdId())) {
1056	                count++;
1057	            }
1058	        }
1059	        owner.setHouseholdMemberCount(count);
1060	    }
1061	
1062	    /**
1063	     * Returns the first {@code length} characters of the SHA-256 digest of {@code input}, rendered as
1064	     * upper-case hexadecimal. Used to derive the {@code memberId} HASH8 segment and the household
1065	     * identifier, both stable functions of their inputs.
1066	     */
1067	    private static String shaHexUpper(String input, int length) {
1068	        try {
1069	            byte[] digest = MessageDigest.getInstance("SHA-256")
1070	                .digest(input.getBytes(StandardCharsets.UTF_8));
1071	            StringBuilder hex = new StringBuilder(digest.length * 2);
1072	            for (byte b : digest) {
1073	                hex.append(String.format("%02x", b));
1074	            }
1075	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
1076	        } catch (NoSuchAlgorithmException ex) {
1077	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
1078	        }
1079	    }
1080	}
